Object.assign(SNIP,{"h24bfs": "int n, m;\ncin >> n >> m;\nvector<vector<int>> adj(n + 1);\nfor (int i = 0; i < m; i++) {\n    int u, v;\n    cin >> u >> v;\n    adj[u].push_back(v);\n    adj[v].push_back(u);              // đồ thị vô hướng: thêm cả hai chiều\n}\nvector<int> d(n + 1, -1);             // -1: chưa thăm\nqueue<int> q;\nd[1] = 0;\nq.push(1);\nwhile (!q.empty()) {\n    int u = q.front(); q.pop();\n    for (int v : adj[u])\n        if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }\n}"});PRESET_NOTES["l24"]={"Ví dụ: BFS tính khoảng cách": "Đỉnh 4 cách đỉnh 1 hai cạnh (qua 2 hoặc 3). Đỉnh 5, 6 nằm ở vùng khác nên giữ −1.", "Ví dụ: Đếm thành phần liên thông": "Hai vùng: {1, 2, 3, 4} và {5, 6}. Mỗi lần gặp đỉnh chưa thăm là một vùng mới; BFS từ đó tô cả vùng.", "Ví dụ: BFS từ hai đỉnh": "Đường ngắn nhất 1 → 4 dài 2; mọi đỉnh v có dS[v] + dT[v] = 2 đều nằm trên một đường ngắn nhất (ở đây là cả 1, 2, 3, 4)."};EX_HINTS["l24"]=[["Code mẫu nới lỏng mọi cạnh nhiều vòng: đồ thị dạng đường thẳng cần n vòng, O(n · m).", "BFS từ đỉnh 1 với mảng d khởi tạo −1; đáp án d[n] (giữ −1 nếu không tới).", "Đồ thị vô hướng: thêm cả adj[u] ← v và adj[v] ← u."], ["Code mẫu đổi tên cả nhóm cho mỗi dây: O(n · m).", "Duyệt s = 1 … n, gặp máy chưa thăm thì tăng bộ đếm và BFS tô cả nhóm.", "Hoặc dùng DSU (khóa Giải thuật Bài 38)."], ["BFS hai lần: từ s được dS, từ t được dT.", "Gặp ở thành phố v mất max(dS[v], dT[v]) giờ; lấy nhỏ nhất trên các v mà cả hai tới được.", "Không v nào cả hai tới được thì in −1. s = t thì đáp án 0."]];
/* ===================== BÀI 24 · Đồ thị: BFS và DFS ===================== */
