const PR24=[{label:"Ví dụ: BFS tính khoảng cách",input:"6 5\n1 2\n1 3\n2 4\n3 4\n5 6\n",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> d(n + 1, -1);\n    queue<int> q;\n    d[1] = 0;\n    q.push(1);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u])\n            if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }\n    }\n    for (int v = 1; v <= n; v++) cout << d[v] << \" \";\n    cout << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,lab:"d",cur:["u","v"]},{type:"cont",of:"q"}]},{label:"Ví dụ: Đếm thành phần liên thông",input:"6 5\n1 2\n1 3\n2 4\n3 4\n5 6\n",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> vung(n + 1, 0);        // 0: chưa thăm; k: thuộc vùng thứ k\n    int dem = 0;\n    for (int s = 1; s <= n; s++) {\n        if (vung[s]) continue;\n        dem++;\n        queue<int> q;\n        vung[s] = dem;\n        q.push(s);\n        while (!q.empty()) {\n            int u = q.front(); q.pop();\n            for (int v : adj[u])\n                if (!vung[v]) { vung[v] = dem; q.push(v); }\n        }\n    }\n    cout << dem << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,lab:"vung",cur:["u","v"]}]},{label:"Ví dụ: BFS từ hai đỉnh",input:"6 5\n1 2\n1 3\n2 4\n3 4\n5 6\n",code:"#include <bits/stdc++.h>\nusing namespace std;\n\nint n, m;\nvector<vector<int>> adj;\n\nvector<int> bfs(int s) {\n    vector<int> d(n + 1, -1);\n    queue<int> q;\n    d[s] = 0;\n    q.push(s);\n    while (!q.empty()) {\n        int u = q.front(); q.pop();\n        for (int v : adj[u])\n            if (d[v] == -1) { d[v] = d[u] + 1; q.push(v); }\n    }\n    return d;\n}\n\nint main() {\n    cin >> n >> m;\n    adj.resize(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    vector<int> dS = bfs(1), dT = bfs(4);\n    for (int v = 1; v <= 4; v++)       // đường đi ngắn nhất từ 1 tới 4 đi qua v\n        cout << v << \": \" << dS[v] + dT[v] << \"\\n\";\n    return 0;\n}",viz:[{type:"graph",adj:"adj",base:1,lab:"d",cur:["u","v"]}]}];
