makeEx2(document.getElementById("ex-l24"),sim24,[{t:"Chuyển thư",d:"File CHUYENTHU.INP: dòng 1 là n, m (2 ≤ n ≤ 10⁵, 0 ≤ m ≤ 2·10⁵); m dòng sau mỗi dòng hai số u, v: có đường hai chiều giữa thành phố u và v. Ghi vào CHUYENTHU.OUT số con đường ít nhất phải đi từ thành phố 1 tới thành phố n, hoặc −1 nếu không tới được.",tests:[{in:"6 5\n1 2\n1 3\n2 4\n3 4\n4 6",out:"3"},{in:"2 0",out:"-1"},{in:"2 1\n1 2",out:"1"},{in:"5 3\n1 2\n2 3\n4 5",out:"-1"},{in:"30 40\n10 16\n16 26\n6 16\n6 7\n7 30\n24 30\n16 28\n10 28\n20 27\n9 25\n24 28\n9 24\n10 11\n5 27\n4 10\n6 22\n11 29\n9 18\n20 26\n1 17\n19 27\n23 25\n7 16\n3 22\n15 22\n5 21\n7 11\n13 23\n2 30\n4 21\n10 23\n3 19\n3 18\n12 21\n8 22\n3 24\n5 26\n5 11\n22 29\n1 25",out:"4"},{in:"50 60\n6 39\n18 30\n5 30\n38 42\n15 42\n22 48\n2 42\n39 41\n9 34\n6 22\n17 35\n11 15\n10 19\n7 20\n18 29\n33 49\n27 42\n10 48\n19 22\n17 20\n4 32\n5 38\n21 47\n3 6\n20 24\n25 44\n2 31\n10 50\n25 27\n36 45\n14 29\n42 44\n9 40\n27 43\n16 39\n34 46\n6 49\n4 8\n7 16\n25 42\n32 34\n9 29\n20 48\n8 12\n34 37\n26 27\n12 22\n13 34\n19 26\n24 49\n1 45\n32 35\n2 16\n9 12\n15 19\n1 26\n26 41\n21 46\n10 12\n4 6",out:"4"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"CHUYENTHU.INP\", \"r\")) {\n        freopen(\"CHUYENTHU.INP\", \"r\", stdin);\n        freopen(\"CHUYENTHU.OUT\", \"w\", stdout);\n    }\n    int n, m;\n    cin >> n >> m;\n    vector<pair<int, int>> e(m);\n    for (auto& [u, v] : e) cin >> u >> v;\n    vector<int> d(n + 1, -1);\n    d[1] = 0;\n    bool doi = true;\n    while (doi) {                      // nới lỏng mọi cạnh cho tới khi không đổi: O(n · m)\n        doi = false;\n        for (auto [u, v] : e) {\n            if (d[u] != -1 && (d[v] == -1 || d[u] + 1 < d[v])) { d[v] = d[u] + 1; doi = true; }\n            if (d[v] != -1 && (d[u] == -1 || d[v] + 1 < d[u])) { d[u] = d[v] + 1; doi = true; }\n        }\n    }\n    cout << d[n] << \"\\n\";\n    return 0;\n}",file:"CHUYENTHU",perf:{gen:n=>{const e=[];for(let i=n;i>1;i--)e.push(i+" "+(i-1));return n+" "+(n-1)+"\n"+e.join("\n")},ns:[100,400,1600],need:"n",limit:n=>120*n+2000,why:"Nới lỏng lặp lại là O(n · m); BFS là O(n + m)."}},{t:"Mạng máy tính",d:"File MANGMAY.INP: dòng 1 là n, m (1 ≤ n ≤ 10⁵, 0 ≤ m ≤ 2·10⁵); m dòng sau mỗi dòng hai máy u, v được nối dây. Hai máy liên lạc được nếu có đường dây nối (trực tiếp hoặc qua máy khác). Ghi vào MANGMAY.OUT số nhóm máy liên lạc được với nhau.",tests:[{in:"6 5\n1 2\n1 3\n2 4\n3 4\n5 6",out:"2"},{in:"1 0",out:"1"},{in:"5 0",out:"5"},{in:"4 3\n1 2\n2 3\n3 4",out:"1"},{in:"40 25\n2 40\n8 39\n14 34\n17 34\n16 33\n5 35\n24 40\n1 31\n15 39\n13 38\n8 10\n13 39\n12 22\n11 18\n10 25\n19 38\n7 23\n29 34\n11 34\n2 20\n9 35\n11 19\n14 23\n5 16\n24 38",out:"15"},{in:"60 50\n7 55\n13 37\n23 59\n10 39\n23 47\n10 33\n15 31\n31 40\n37 51\n1 11\n13 46\n3 9\n21 47\n5 14\n7 57\n8 18\n15 55\n1 9\n1 34\n9 44\n48 59\n40 51\n19 59\n11 54\n22 42\n16 26\n18 28\n11 43\n24 39\n12 41\n14 56\n37 48\n10 27\n34 51\n28 50\n20 51\n40 55\n15 47\n27 35\n19 50\n17 53\n50 56\n8 47\n28 60\n29 54\n39 51\n13 42\n21 59\n8 15\n41 50",out:"15"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"MANGMAY.INP\", \"r\")) {\n        freopen(\"MANGMAY.INP\", \"r\", stdin);\n        freopen(\"MANGMAY.OUT\", \"w\", stdout);\n    }\n    int n, m;\n    cin >> n >> m;\n    vector<int> nhom(n + 1);\n    for (int i = 1; i <= n; i++) nhom[i] = i;\n    for (int k = 0; k < m; k++) {\n        int u, v;\n        cin >> u >> v;\n        int a = nhom[u], b = nhom[v];\n        if (a != b)\n            for (int i = 1; i <= n; i++) if (nhom[i] == b) nhom[i] = a;   // đổi tên cả nhóm: O(n) mỗi cạnh\n    }\n    int dem = 0;\n    for (int i = 1; i <= n; i++) if (nhom[i] == i) dem++;\n    cout << dem << \"\\n\";\n    return 0;\n}",file:"MANGMAY",perf:{gen:n=>{const e=[];for(let i=1;i<n;i++)e.push(i+" "+(i+1));return n+" "+(n-1)+"\n"+e.join("\n")},ns:[100,400,1600],need:"n",limit:n=>120*n+2000,why:"Đổi tên nhóm cho mỗi cạnh là O(n · m); BFS đếm vùng là O(n + m)."}},{t:"Hẹn gặp",d:"File HENGAP.INP: dòng 1 là n, m (2 ≤ n ≤ 10⁵, 0 ≤ m ≤ 2·10⁵); m dòng tiếp mỗi dòng hai số u, v (đường hai chiều, đi mất 1 giờ); dòng cuối là s, t: An ở thành phố s, Bình ở thành phố t. Hai bạn cùng xuất phát, chọn một thành phố để gặp nhau; thời gian chờ gặp là thời gian của bạn đến muộn hơn. Ghi vào HENGAP.OUT thời gian nhỏ nhất để gặp nhau, hoặc −1 nếu không thể.",tests:[{in:"5 4\n1 2\n2 3\n3 4\n4 5\n1 5",out:"2"},{in:"2 1\n1 2\n1 2",out:"1"},{in:"3 1\n1 2\n1 3",out:"-1"},{in:"4 3\n1 2\n2 3\n3 4\n2 2",out:"0"},{in:"30 45\n4 13\n7 30\n5 11\n11 21\n11 19\n5 28\n1 7\n15 21\n7 24\n7 15\n8 22\n13 26\n4 18\n2 22\n10 29\n6 22\n26 30\n28 30\n25 29\n5 22\n10 28\n7 13\n18 29\n8 25\n11 22\n8 19\n16 30\n17 19\n4 19\n13 14\n19 22\n6 24\n8 14\n8 18\n5 7\n12 30\n1 30\n6 25\n5 24\n3 21\n9 14\n5 9\n8 15\n19 21\n2 13\n1 30",out:"1"},{in:"50 70\n13 47\n21 50\n32 49\n24 46\n24 42\n2 19\n1 28\n4 25\n15 48\n16 41\n32 39\n12 28\n12 45\n21 26\n6 15\n8 10\n6 41\n39 50\n18 41\n9 39\n4 17\n1 19\n17 24\n24 49\n19 50\n6 13\n42 45\n3 13\n13 50\n30 31\n2 11\n39 48\n2 29\n11 27\n13 14\n26 37\n24 37\n25 34\n5 9\n4 10\n45 47\n8 41\n10 43\n37 45\n16 43\n1 2\n7 26\n18 25\n2 45\n23 29\n1 47\n18 28\n38 43\n6 10\n2 7\n41 49\n11 18\n22 38\n11 19\n5 17\n17 23\n11 30\n35 47\n3 22\n30 47\n9 26\n8 24\n6 38\n5 37\n31 39\n3 7",out:"3"}],start:"#include <bits/stdc++.h>\nusing namespace std;\n\nint main() {\n    ios::sync_with_stdio(false);\n    cin.tie(nullptr);\n    if (fopen(\"HENGAP.INP\", \"r\")) {\n        freopen(\"HENGAP.INP\", \"r\", stdin);\n        freopen(\"HENGAP.OUT\", \"w\", stdout);\n    }\n    int n, m;\n    cin >> n >> m;\n    vector<vector<int>> adj(n + 1);\n    for (int i = 0; i < m; i++) {\n        int u, v;\n        cin >> u >> v;\n        adj[u].push_back(v);\n        adj[v].push_back(u);\n    }\n    int s, t;\n    cin >> s >> t;\n    // BFS từ s và từ t, rồi xét từng thành phố\n    cout << -1 << \"\\n\";\n    return 0;\n}",file:"HENGAP"}]);

